package com.bookstore.user.entity;
import jakarta.persistence.*; import com.fasterxml.jackson.annotation.JsonIgnore; import java.time.LocalDateTime;
@Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String username; @JsonIgnore @Column(nullable=false) private String password; @Column(name="full_name",nullable=false) private String fullName; @Column(nullable=false,unique=true) private String email; private String phone; @Column(nullable=false) private String role="CUSTOMER"; @Column(name="created_at") private LocalDateTime createdAt=LocalDateTime.now(); @Column(name="updated_at") private LocalDateTime updatedAt=LocalDateTime.now(); public User(){} public Long getId(){return id;} public String getUsername(){return username;} public void setUsername(String v){username=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getRole(){return role;} public void setRole(String v){role=v;} }
